515			t.Fatalf("fetch after revoke err = %v", err)
516		}
517		// 回执仍可登记，确认中不含包内容。
518		conf, err := f.s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptAccepted, "")
519		if err != nil {
520			t.Fatalf("receipt after revoke: %v", err)
521		}
522		if conf.Status != ExchangeAccepted {
523			t.Fatalf("status = %q", conf.Status)
524		}
525	
526		// 停用后再对第二份包登记回执。
527		x2, err := f.s.CreateExchange(doc, f.pid, rcv.ID, mustGrant(t, f), []ID{f.ord}, "req-late-2")
528		if err != nil {
529			t.Fatal(err)
530		}
531		if err := f.s.DeactivatePatient(doc, f.pid); err != nil {
532			t.Fatal(err)
533		}
534		if _, err := f.s.FetchPackage(rcv, x2.ID); !errors.Is(err, ErrAccessDenied) {
535			t.Fatalf("fetch after deactivate err = %v", err)
536		}
537		conf2, err := f.s.SubmitReceipt(rcv, x2.ID, x2.Digest, ReceiptRejected, "停用前已收到")
538		if err != nil {
539			t.Fatalf("receipt after deactivate: %v", err)
540		}
541		if conf2.Status != ExchangeRejected {
542			t.Fatalf("status = %q", conf2.Status)
543		}
544	}
