689	
690	func TestExchangePersistenceAcrossReopen(t *testing.T) {
691		dir := t.TempDir()
692		clk := &fakeClock{t: time.Date(2026, 4, 1, 8, 0, 0, 0, time.UTC)}
693		open := func() *Store {
694			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
695			if err != nil {
696				t.Fatalf("open: %v", err)
697			}
698			return s
699		}
700	
701		s := open()
702		p, _ := s.RegisterPatient(doc, "持久化交换患者")
703		e, _ := s.AddEncounter(doc, p.ID, time.Time{})
704		rec, _ := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "包内v1")
705		v1, _ := s.ActivateRecord(doc, rec.ID)
706		a, _ := s.Grant(doc, p.ID, rcv.ID, []Scope{{EncounterID: e.ID, Category: Diagnosis}},
707			clk.t.Add(-time.Hour), clk.t.Add(48*time.Hour))
708	
709		x, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rec.ID}, "req-persist")
710		if err != nil {
711			t.Fatal(err)
712		}
713		// 打包后更正：包固定在 v1。
714		if _, err := s.CorrectRecord(doc, rec.ID, 1, "当前v2", "事后更正"); err != nil {
715			t.Fatal(err)
716		}
717		if _, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, "重开前拒绝"); err != nil {
718			t.Fatal(err)
719		}
720		if err := s.Close(); err != nil {
721			t.Fatal(err)
722		}
723	
724		s2 := open()
725		t.Cleanup(func() { _ = s2.Close() })
726	
727		// 原包内容固定为 v1，回执保留。
728		got, err := s2.GetExchange(doc, p.ID, x.ID)
729		if err != nil {
730			t.Fatalf("get after reopen: %v", err)
731		}
732		if got.Status != ExchangeRejected || got.Receipt == nil || got.Receipt.Reason != "重开前拒绝" {
733			t.Fatalf("receipt lost: %+v", got)
734		}
735		if len(got.Package.Records) != 1 || got.Package.Records[0].VersionID != v1.ID ||
736			got.Package.Records[0].Content != "包内v1" {
737			t.Fatalf("frozen package lost: %+v", got.Package.Records)
738		}
739	
740		// 同请求号重试仍返回原交换，不新增审计。
741		auditBefore := len(mustAudit(t, s2, p.ID))
742		retry, err := s2.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rec.ID}, "req-persist")
743		if err != nil {
744			t.Fatalf("retry after reopen: %v", err)
745		}
746		if retry.ID != x.ID || retry.Status != ExchangeRejected {
747			t.Fatalf("retry after reopen = %+v", retry)
748		}
749		if retry.Package.Records[0].Content != "包内v1" {
750			t.Fatalf("retry refetched current content: %+v", retry.Package.Records)
751		}
752		if n := len(mustAudit(t, s2, p.ID)); n != auditBefore {
753			t.Fatalf("retry after reopen added audit: %d", n)
754		}
755	
756		// 审计两类事件都在。
757		var creates, receipts int
758		for _, ev := range mustAudit(t, s2, p.ID) {
759			switch ev.Action {
760			case ActionExchanged:
761				creates++
762			case ActionReceipted:
763				receipts++
764			}
765		}
766		if creates != 1 || receipts != 1 {
767			t.Fatalf("audit after reopen: creates=%d receipts=%d", creates, receipts)
768		}
769	
770		// 取包路径在重开后同样按当前时间与绑定授权判断（窗口内可取）。
771		del, err := s2.FetchPackage(rcv, x.ID)
772		if err != nil {
773			t.Fatalf("fetch after reopen: %v", err)
774		}
775		if del.Digest != x.Digest || del.Status != ExchangeRejected {
776			t.Fatalf("delivery after reopen wrong: %+v", del)
777		}
