101	func assertExchangeMatches(t *testing.T, got, want Exchange, label string) {
102		t.Helper()
103		if got.ID != want.ID || got.Status != want.Status || got.Digest != want.Digest ||
104			got.PatientID != want.PatientID || got.ReceiverID != want.ReceiverID ||
105			got.AuthorizationID != want.AuthorizationID || got.RequestID != want.RequestID ||
106			got.CreatorID != want.CreatorID || !got.CreatedAt.Equal(want.CreatedAt) {
107			t.Fatalf("%s: exchange header changed:\n got=%+v\nwant=%+v", label, got, want)
108		}
109		if got.Package.PatientID != want.Package.PatientID || got.Package.ReceiverID != want.Package.ReceiverID {
110			t.Fatalf("%s: package header changed:\n got=%+v\nwant=%+v", label, got.Package, want.Package)
111		}
112		if len(got.Package.Records) != len(want.Package.Records) {
113			t.Fatalf("%s: record set changed: got %d records %+v, want %d records %+v",
114				label, len(got.Package.Records), got.Package.Records, len(want.Package.Records), want.Package.Records)
115		}
116		gm := recordsByID(got.Package.Records)
117		wm := recordsByID(want.Package.Records)
118		if len(gm) != len(wm) {
119			t.Fatalf("%s: duplicate record ids after mutation: %+v", label, got.Package.Records)
120		}
121		for rid, wr := range wm {
122			gr, ok := gm[rid]
123			if !ok {
124				t.Fatalf("%s: record %q missing from package: %+v", label, rid, got.Package.Records)
125			}
126			if gr != wr {
127				t.Fatalf("%s: record %q changed:\n got=%+v\nwant=%+v", label, rid, gr, wr)
128			}
129		}
130		if (got.Receipt == nil) != (want.Receipt == nil) {
131			t.Fatalf("%s: receipt presence changed: got present=%v, want present=%v",
132				label, got.Receipt != nil, want.Receipt != nil)
133		}
134		if want.Receipt != nil {
135			if got.Receipt.Outcome != want.Receipt.Outcome || got.Receipt.Reason != want.Receipt.Reason ||
136				!got.Receipt.RegisteredAt.Equal(want.Receipt.RegisteredAt) {
137				t.Fatalf("%s: receipt changed:\n got=%+v\nwant=%+v", label, *got.Receipt, *want.Receipt)
138			}
139		}
140	}
141	
142	func assertDeliveryMatches(t *testing.T, got, want PackageDelivery, label string) {
143		t.Helper()
144		if got.ExchangeID != want.ExchangeID || got.Status != want.Status ||
145			got.Digest != want.Digest || !got.CreatedAt.Equal(want.CreatedAt) {
146			t.Fatalf("%s: delivery header changed:\n got=%+v\nwant=%+v", label, got, want)
147		}
148		if got.Package.PatientID != want.Package.PatientID || got.Package.ReceiverID != want.Package.ReceiverID {
149			t.Fatalf("%s: delivery package header changed:\n got=%+v\nwant=%+v", label, got.Package, want.Package)
150		}
151		if len(got.Package.Records) != len(want.Package.Records) {
152			t.Fatalf("%s: delivery record set changed: got %+v, want %+v",
153				label, got.Package.Records, want.Package.Records)
154		}
155		gm := recordsByID(got.Package.Records)
156		wm := recordsByID(want.Package.Records)
157		if len(gm) != len(wm) {
158			t.Fatalf("%s: duplicate record ids after mutation: %+v", label, got.Package.Records)
159		}
160		for rid, wr := range wm {
161			gr, ok := gm[rid]
162			if !ok {
163				t.Fatalf("%s: record %q missing from delivery: %+v", label, rid, got.Package.Records)
164			}
165			if gr != wr {
166				t.Fatalf("%s: delivery record %q changed:\n got=%+v\nwant=%+v", label, rid, gr, wr)
167			}
168		}
169	}
