598			if err != nil {
599				t.Fatalf("open: %v", err)
600			}
601			return s
602		}
603	
604		s := open()
605		p, err := s.RegisterPatient(doc, "重开隔离患者")
606		if err != nil {
607			t.Fatal(err)
608		}
609		enc, err := s.AddEncounter(doc, p.ID, time.Time{})
610		if err != nil {
611			t.Fatal(err)
612		}
613		recD, _ := s.CreateDraft(doc, p.ID, enc.ID, Diagnosis, "诊断内容")
614		if _, err := s.ActivateRecord(doc, recD.ID); err != nil {
615			t.Fatal(err)
616		}
617		recO, _ := s.CreateDraft(doc, p.ID, enc.ID, Order, "医嘱内容")
618		if _, err := s.ActivateRecord(doc, recO.ID); err != nil {
619			t.Fatal(err)
620		}
621		a, err := s.Grant(doc, p.ID, rcv.ID,
622			[]Scope{{EncounterID: enc.ID, Category: Diagnosis}, {EncounterID: enc.ID, Category: Order}},
623			clk.t.Add(-time.Hour), clk.t.Add(48*time.Hour))
624		if err != nil {
625			t.Fatal(err)
626		}
627		x, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID,
628			[]ID{recD.ID, recO.ID}, "req-reopen-iso")
629		if err != nil {
630			t.Fatal(err)
631		}
632		want := snapshotExchange(x)
633	
634		// 从每一个返回入口取得结果并全部在本地篡改。
635		g, err := s.GetExchange(doc, p.ID, x.ID)
636		if err != nil {
637			t.Fatal(err)
638		}
639		tamperExchangeResult(&g)
640	
641		lst, err := s.ListExchanges(doc, p.ID)
642		if err != nil {
643			t.Fatal(err)
644		}
645		tamperExchangeResult(&lst[0])
646	
647		retry, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID,
648			[]ID{recO.ID, recD.ID}, "req-reopen-iso")
649		if err != nil {
650			t.Fatal(err)
651		}
652		tamperExchangeResult(&retry)
653	
654		d, err := s.FetchPackage(rcv, x.ID)
655		if err != nil {
656			t.Fatal(err)
657		}
658		tamperDeliveryResult(&d)
659	
660		// 触发一次真实的整体原子写盘（幂等重试会克隆当前状态并落盘）。
661		again, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID,
662			[]ID{recD.ID, recO.ID}, "req-reopen-iso")
663		if err != nil {
664			t.Fatalf("retry that forces persist: %v", err)
665		}
666		assertExchangeMatches(t, again, want, "force-persist retry still returns original")
667	
668		if err := s.Close(); err != nil {
669			t.Fatal(err)
670		}
671	
672		s2 := open()
673		t.Cleanup(func() { _ = s2.Close() })
674	
675		got, err := s2.GetExchange(doc, p.ID, x.ID)
676		if err != nil {
677			t.Fatalf("get after reopen: %v", err)
678		}
679		assertExchangeMatches(t, got, want, "exchange after reopen")
680	
681		gotList, err := s2.ListExchanges(doc, p.ID)
682		if err != nil {
683			t.Fatal(err)
684		}
685		if len(gotList) != 1 {
686			t.Fatalf("list after reopen len = %d, want 1", len(gotList))
687		}
688		assertExchangeMatches(t, gotList[0], want, "list after reopen")
689	
690		acts := auditActions(mustAudit(t, s2, p.ID))
691		if acts[ActionExchanged] != 1 {
692			t.Fatalf("exchange_created audits after reopen = %d, want 1", acts[ActionExchanged])
693		}
694		if acts[ActionReceipted] != 0 {
695			t.Fatalf("receipt audits after reopen = %d, want 0", acts[ActionReceipted])
696		}
697	}
